CREATE OR REPLACE FUNCTION public.complete_health_probe(p_credential_id uuid, p_success boolean, p_min_interval_seconds integer, p_failure_backoff_seconds integer, p_max_backoff_seconds integer, p_result text, p_reservation_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare failures integer; delay_seconds integer;
begin
 select case when p_success then 0 else consecutive_failures+1 end into failures from public.health_probe_state where credential_id=p_credential_id and reservation_token=p_reservation_token and lease_until is not null for update;
 if failures is null then return; end if;
 delay_seconds := case when p_success then p_min_interval_seconds else least(p_max_backoff_seconds,p_failure_backoff_seconds * power(2,least(greatest(failures-1,0),10))::integer) end;
 update public.health_probe_state set consecutive_failures=failures,next_allowed_at=now()+make_interval(secs=>delay_seconds),lease_until=null,reservation_token=null,last_result=p_result,updated_at=now() where credential_id=p_credential_id and reservation_token=p_reservation_token;
end; $function$

CREATE OR REPLACE FUNCTION public.reserve_client_quota(p_client_id uuid, p_requests_per_minute integer, p_tokens_per_minute bigint, p_estimated_tokens bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_window timestamptz := date_trunc('minute', now());
  current_requests integer;
  current_tokens bigint;
begin
  if p_estimated_tokens < 0 then
    return 'tokens';
  end if;

  insert into client_quota_windows(client_id, window_started_at)
  values (p_client_id, current_window)
  on conflict (client_id, window_started_at) do nothing;

  select request_count, token_count
    into current_requests, current_tokens
    from client_quota_windows
   where client_id = p_client_id and window_started_at = current_window
   for update;

  if p_requests_per_minute is not null
     and current_requests + 1 > p_requests_per_minute then
    return 'requests';
  end if;
  if p_tokens_per_minute is not null
     and current_tokens + p_estimated_tokens > p_tokens_per_minute then
    return 'tokens';
  end if;

  update client_quota_windows
     set request_count = request_count + 1,
         token_count = token_count + p_estimated_tokens
   where client_id = p_client_id and window_started_at = current_window;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_client_spending(p_client_id uuid, p_estimated_cost numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  current_window timestamptz := date_trunc('month', now());
  limit_amount numeric;
  used numeric;
begin
  if p_estimated_cost is null then return null; end if;
  if p_estimated_cost < 0 then return 'invalid_cost'; end if;

  select c.spending_limit into limit_amount
    from gateway_clients c where c.id = p_client_id;
  if limit_amount is null then return null; end if;

  insert into client_spend_windows(client_id, window_started_at)
  values (p_client_id, current_window)
  on conflict (client_id, window_started_at) do nothing;

  select reserved_cost into used from client_spend_windows
   where client_id = p_client_id and window_started_at = current_window
   for update;

  if used + p_estimated_cost > limit_amount then
    return 'spending_limit';
  end if;

  update client_spend_windows
     set reserved_cost = reserved_cost + p_estimated_cost,
         request_count = request_count + 1,
         updated_at = now()
   where client_id = p_client_id and window_started_at = current_window;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_gateway_budgets(p_client_id uuid, p_provider_id uuid, p_credential_id uuid, p_model_id text, p_route_id uuid, p_currency text, p_estimated_cost numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  budget record;
  window_start timestamptz;
  used numeric;
begin
  if p_estimated_cost is null or p_currency is null then return null; end if;
  if p_estimated_cost < 0 then return 'invalid_cost'; end if;

  for budget in
    select * from gateway_budgets b where b.enabled
      and b.enforcement='block' and b.currency=upper(p_currency) and (
        b.scope_type='global' or
        (b.scope_type='client' and b.scope_id=p_client_id::text) or
        (b.scope_type='provider' and b.scope_id=p_provider_id::text) or
        (b.scope_type='credential' and b.scope_id=p_credential_id::text) or
        (b.scope_type='model' and b.scope_id=p_model_id) or
        (b.scope_type='route' and b.scope_id=p_route_id::text)
      ) order by b.id for update
  loop
    window_start := case budget.period when 'daily' then date_trunc('day',now())
      else date_trunc('month',now()) end;
    insert into budget_usage_windows(budget_id,window_started_at)
      values(budget.id,window_start) on conflict do nothing;
    select reserved_cost into used from budget_usage_windows
      where budget_id=budget.id and window_started_at=window_start for update;
    if used+p_estimated_cost > budget.limit_amount then return budget.id::text; end if;
  end loop;

  for budget in
    select * from gateway_budgets b where b.enabled and b.currency=upper(p_currency) and (
      b.scope_type='global' or
      (b.scope_type='client' and b.scope_id=p_client_id::text) or
      (b.scope_type='provider' and b.scope_id=p_provider_id::text) or
      (b.scope_type='credential' and b.scope_id=p_credential_id::text) or
      (b.scope_type='model' and b.scope_id=p_model_id) or
      (b.scope_type='route' and b.scope_id=p_route_id::text)
    ) order by b.id for update
  loop
    window_start := case budget.period when 'daily' then date_trunc('day',now())
      else date_trunc('month',now()) end;
    insert into budget_usage_windows(budget_id,window_started_at)
      values(budget.id,window_start) on conflict do nothing;
    update budget_usage_windows set reserved_cost=reserved_cost+p_estimated_cost,
      request_count=request_count+1,updated_at=now()
      where budget_id=budget.id and window_started_at=window_start;
  end loop;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_health_probe(p_provider_id uuid, p_credential_id uuid, p_provider_model_id uuid, p_daily_limit integer, p_min_interval_seconds integer, p_lease_seconds integer, p_manual boolean DEFAULT false, p_manual_daily_limit integer DEFAULT 20, p_manual_min_interval_seconds integer DEFAULT 60)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare state public.health_probe_state%rowtype; token uuid;
begin
 insert into public.health_probe_state(credential_id,provider_id,provider_model_id) values(p_credential_id,p_provider_id,p_provider_model_id) on conflict(credential_id) do nothing;
 select * into state from public.health_probe_state where credential_id=p_credential_id for update;
 if state.window_started_at < current_date then update public.health_probe_state set window_started_at=current_date,request_count=0,manual_request_count=0,updated_at=now() where credential_id=p_credential_id returning * into state; end if;
 if state.lease_until is not null and state.lease_until > now() then return 'in_progress'; end if;
 if p_manual and state.manual_request_count >= p_manual_daily_limit then return 'manual_daily_limit'; end if;
 if p_manual and state.manual_last_attempt_at is not null and state.manual_last_attempt_at > now()-make_interval(secs=>p_manual_min_interval_seconds) then return 'manual_cooldown'; end if;
 if not p_manual and state.request_count >= p_daily_limit then return 'daily_limit'; end if;
 if not p_manual and state.next_allowed_at is not null and state.next_allowed_at > now() then return 'cooldown'; end if;
 token := gen_random_uuid();
 update public.health_probe_state set provider_id=p_provider_id,provider_model_id=p_provider_model_id,request_count=request_count+case when p_manual then 0 else 1 end,manual_request_count=manual_request_count+case when p_manual then 1 else 0 end,manual_last_attempt_at=case when p_manual then now() else manual_last_attempt_at end,last_attempt_at=now(),next_allowed_at=now()+make_interval(secs=>p_min_interval_seconds),lease_until=now()+make_interval(secs=>p_lease_seconds),reservation_token=token,updated_at=now() where credential_id=p_credential_id;
 return 'reserved:' || token::text;
end; $function$
